-- My Pretty Pulls: Guess the Secret Pull
-- Run once in Supabase: SQL Editor > New query > paste > Run.
-- The "destructive operations" warning is expected (it refreshes the card list).

-- Card list the game checks answers against (public card info, safe to read)
create table if not exists public.game_cards (
  uid text primary key, num text not null, n int not null, rar text not null,
  editions text[] not null, name text not null, main text, appears text[] not null
);
-- Blurry previews of each card, only handed out by the game as you play
create table if not exists public.game_mosaics (
  uid text references public.game_cards(uid) on delete cascade, level smallint, w smallint, h smallint, px text not null,
  primary key (uid, level)
);
-- A private random value so nobody can work out future cards
create table if not exists public.game_config (id int primary key default 1 check (id = 1), seed text not null);
-- Each signed-in player's game for each day
create table if not exists public.secret_pull_plays (
  user_id uuid references auth.users(id) on delete cascade,
  day date not null,
  log jsonb not null default '[]',
  used smallint not null default 0,
  solved boolean not null default false,
  finished boolean not null default false,
  points smallint not null default 0,
  finished_at timestamptz,
  primary key (user_id, day)
);

alter table public.game_cards enable row level security;
alter table public.game_mosaics enable row level security;
alter table public.game_config enable row level security;
alter table public.secret_pull_plays enable row level security;
-- Nobody reads these tables directly; the functions below do it safely.
revoke all on public.game_cards, public.game_mosaics, public.game_config, public.secret_pull_plays from anon, authenticated;

truncate public.game_cards cascade;

-- Today's game day (US Eastern time) and puzzle number
create or replace function public.sp_today() returns date language sql stable as $$
  select (now() at time zone 'America/New_York')::date;
$$;
create or replace function public.sp_card_for(d date) returns text language sql stable security definer set search_path = public as $$
  select uid from game_cards order by md5(uid || (select seed from game_config) || d::text) limit 1;
$$;
revoke all on function public.sp_card_for(date) from public, anon, authenticated;

-- Does today's card match this question?
create or replace function public.sp_check(card text, q text) returns boolean language plpgsql stable security definer set search_path = public as $$
declare c game_cards; parts text[] := string_to_array(q, ':');
begin
  select * into c from game_cards where uid = card;
  case parts[1]
    when 'ed'   then return parts[2] = any(c.editions);
    when 'rar'  then return c.rar = parts[2];
    when 'hit'  then return c.rar not in ('R','QR','SR','PR');
    when 'solo' then return c.main is not null and cardinality(c.appears) = 1;
    when 'char' then return parts[2] = any(c.appears);
    when 'grp'  then return c.appears && (case parts[2]
        when 'Winx' then array['Bloom','Stella','Flora','Musa','Tecna','Aisha']
        when 'Specialists' then array['Sky','Brandon','Helia','Riven','Timmy','Nabu']
        when 'Trix' then array['Icy','Darcy','Stormy']
        when 'Pets' then array['Kiko','Milly','Belle','Coco','Pepe','Ginger','Chicko']
        when 'Special guests' then array['Zara Larsson']
        else array[]::text[] end);
    when 'gt'   then return c.n > parts[2]::int;
    else raise exception 'Unknown question';
  end case;
end $$;
revoke all on function public.sp_check(text, text) from public, anon, authenticated;

create or replace function public.sp_points(used int, solved boolean) returns int language sql immutable as $$
  select case when not solved then 0 else greatest(2, 10 - used) end;
$$;

create or replace function public.sp_streak(uid uuid) returns int language plpgsql stable security definer set search_path = public as $$
declare d date := sp_today(); n int := 0; s boolean;
begin
  select solved into s from secret_pull_plays where user_id = uid and day = d;
  if not coalesce(s, false) then d := d - 1; end if;  -- today not solved yet: count from yesterday
  loop
    select solved into s from secret_pull_plays where user_id = uid and day = d;
    exit when not coalesce(s, false);
    n := n + 1; d := d - 1;
  end loop;
  return n;
end $$;
revoke all on function public.sp_streak(uuid) from public, anon, authenticated;

-- Where the player stands today. Signed-out players keep their own score on their device.
create or replace function public.sp_state() returns json language plpgsql security definer set search_path = public as $$
declare d date := sp_today(); p secret_pull_plays; uid uuid := auth.uid();
begin
  if uid is not null then select * into p from secret_pull_plays where user_id = uid and day = d; end if;
  return json_build_object(
    'day', d, 'number', d - date '2026-11-05',
    'log', coalesce(p.log, '[]'::jsonb), 'used', coalesce(p.used, 0),
    'finished', coalesce(p.finished, false), 'solved', coalesce(p.solved, false), 'points', coalesce(p.points, 0),
    'card', case when p.finished then sp_card_for(d) end,
    'streak', case when uid is null then 0 else sp_streak(uid) end,
    'total', case when uid is null then 0 else (select coalesce(sum(points),0) from secret_pull_plays where user_id = uid) end);
end $$;

-- Ask a yes/no question (uses one of 8 tries)
create or replace function public.sp_ask(q text) returns json language plpgsql security definer set search_path = public as $$
declare d date := sp_today(); card text := sp_card_for(d); uid uuid := auth.uid(); p secret_pull_plays; ans boolean;
begin
  if q !~ '^(ed:(daily|magic|promo)|rar:[A-Z]{1,4}|hit|solo|char:[A-Za-z ]{2,30}|grp:[A-Za-z ]{2,30}|gt:[0-9]{1,3})$' then raise exception 'Unknown question'; end if;
  ans := sp_check(card, q);
  if uid is not null then
    select * into p from secret_pull_plays where user_id = uid and day = d for update;
    if p.finished then return json_build_object('error', 'finished'); end if;
    if p.used >= 8 then return json_build_object('error', 'no_tries'); end if;
    update secret_pull_plays set used = used + 1, log = log || jsonb_build_array(jsonb_build_object('q', q, 'a', ans))
      where user_id = uid and day = d;
  end if;
  return json_build_object('answer', ans);
end $$;

-- Guess a card. Right: you win. Wrong: uses a try (with 0 left, it ends the game).
create or replace function public.sp_guess(guess text) returns json language plpgsql security definer set search_path = public as $$
declare d date := sp_today(); card text := sp_card_for(d); uid uuid := auth.uid(); p secret_pull_plays; ok boolean := (guess = card); over boolean;
begin
  if uid is null then
    return json_build_object('correct', ok, 'card', case when ok then card end);
  end if;
  select * into p from secret_pull_plays where user_id = uid and day = d for update;
  if p.finished then return json_build_object('error', 'finished'); end if;
  over := ok or p.used >= 8;
  update secret_pull_plays set
      used = case when ok or p.used >= 8 then used else used + 1 end,
      log = log || jsonb_build_array(jsonb_build_object('g', guess, 'a', ok)),
      solved = ok, finished = over, points = sp_points(p.used, ok),
      finished_at = case when over then now() end
    where user_id = uid and day = d;
  return json_build_object('correct', ok, 'finished', over, 'card', case when over then card end, 'points', sp_points(p.used, ok));
end $$;

-- Signed-out players reveal the answer when they run out
create or replace function public.sp_reveal() returns text language plpgsql security definer set search_path = public as $$
declare d date := sp_today(); p secret_pull_plays;
begin
  if auth.uid() is null then return sp_card_for(d); end if;
  select * into p from secret_pull_plays where user_id = auth.uid() and day = d;
  if coalesce(p.finished, false) then return sp_card_for(d); end if;
  return null;
end $$;

-- Blurry preview: sharper as you use tries (2 = level 1, 4 = level 2, 6 = level 3)
create or replace function public.sp_peek(used_count int) returns json language plpgsql security definer set search_path = public as $$
declare d date := sp_today(); u int := used_count; lv int; m game_mosaics;
begin
  if auth.uid() is not null then select coalesce(max(used), 0) into u from secret_pull_plays where user_id = auth.uid() and day = d; end if;
  lv := case when u >= 6 then 3 when u >= 4 then 2 when u >= 2 then 1 else 0 end;
  if lv = 0 then return null; end if;
  select * into m from game_mosaics where uid = sp_card_for(d) and level = lv;
  return json_build_object('level', lv, 'w', m.w, 'h', m.h, 'px', m.px);
end $$;

-- Streak and points for a public profile
create or replace function public.sp_profile_stats(uname text) returns json language sql stable security definer set search_path = public as $$
  select json_build_object('streak', sp_streak(p.id),
    'total', (select coalesce(sum(points),0) from secret_pull_plays where user_id = p.id),
    'solved', (select count(*) from secret_pull_plays where user_id = p.id and solved))
  from profiles p where p.username = lower(uname) and (p.is_public or p.id = auth.uid());
$$;

grant execute on function public.sp_today(), public.sp_points(int, boolean), public.sp_state(), public.sp_ask(text), public.sp_guess(text),
  public.sp_reveal(), public.sp_peek(int), public.sp_profile_stats(text) to anon, authenticated;
